// =====================================================================
//  PARAMÈTRES DE LA VEILLE QUOTIDIENNE : c'est le seul nœud à modifier.
// =====================================================================

// 1) Où envoyer l'alerte et où ranger les signaux
const email = 'ton.email@exemple.com';
const googleSheetUrl = 'https://docs.google.com/spreadsheets/d/COLLE_ICI_L_ID_DE_TA_FEUILLE/edit';

// 2) Tes projets à la ferme : les signaux qui en parlent passent en premier, avec un brief adapté.
//    Remplace par tes vrais projets et leurs mots-clés (français et anglais).
const mesProjets = [
  { nom: 'Pisciculture', mots: ['poisson', 'fish', 'silure', 'tilapia', 'pisciculture', 'aquaculture', 'alevin'] },
  { nom: 'Plantain et palmier à huile', mots: ['plantain', 'banane', 'banana', 'huile de palme', 'palm oil', 'palmier'] },
];

// 3) Mots-clés produits, en français ET en anglais. Un signal n'est gardé que s'il en contient au moins un.
//    Écris-les en minuscules, avec les accents. « bean » trouve aussi « beans », « fertili » trouve « fertilizer ».
const motsCles = [
  'maïs', 'maize', 'riz', 'rice', 'manioc', 'cassava', 'gari', 'tapioca', 'cacao', 'cocoa', 'café', 'coffee',
  'poivre', 'pepper', 'piment', 'chili', 'gingembre', 'ginger', 'sésame', 'sesame', 'soja', 'soybean', 'soya',
  'arachide', 'groundnut', 'peanut', 'oignon', 'onion', 'pomme de terre', 'pommes de terre', 'potato', 'haricot',
  'niébé', 'cowpea', 'sorgho', 'sorghum', 'millet', 'huile de palme', 'palm oil', 'banane', 'banana',
  'plantain', 'ananas', 'pineapple', 'avocado', 'mangue', 'mango', 'cajou', 'cashew', 'karité', 'shea',
  'noix de cola', 'kola', 'volaille', 'poulet', 'poultry', 'chicken', 'œuf', 'oeuf', 'egg', 'poisson', 'fish',
  'semence', 'seed', 'engrais', 'fertili', 'provende', 'aliment pour bétail', 'animal feed', 'farine', 'flour',
  'céréale', 'cereal', 'grain', 'vivres', 'denrée', 'foodstuff', 'food supply', 'sucre', 'sugar',
];

// 4) Mots qui rendent un signal urgent (pénurie, interdiction, flambée des prix…)
const motsAlerte = [
  'pénurie', 'shortage', 'flambée', 'envolée', 'surge', 'spike', 'interdi', 'export ban', 'import ban',
  'suspend', 'rupture', 'crise', 'crisis', 'déficit', 'deficit', "appel d'offres", 'tender',
  'recherche fournisseur', 'seeking supplier', 'looking for supplier',
];

// 5) Une actualité n'est gardée que si elle parle aussi de commerce (évite les articles de cuisine ou de santé)
const motsCommerce = [
  'import', 'export', 'prix', 'price', 'marché', 'market', 'demande', 'demand', 'pénurie', 'shortage', 'cours',
  'filière', 'tonne', 'tons', 'fcfa', 'cfa', 'naira', 'achat', 'buyer', 'supplier', 'fournisseur', 'production',
  'récolte', 'harvest', 'trade', 'commerce', 'tarif', 'douane', 'customs', 'interdi', 'export ban', 'import ban',
  'stock', 'cargaison',
];

// 6) Recherches Google Actualités (même syntaxe que dans Google : OR, guillemets, parenthèses)
const recherchesActualites = [
  { q: 'Cameroun prix (maïs OR riz OR oignon OR "huile de palme" OR poisson)', langue: 'fr' },
  { q: 'Cameroun importation (riz OR poisson OR maïs OR "huile de palme" OR blé)', langue: 'fr' },
  { q: '(Gabon OR Congo OR Tchad OR "Guinée équatoriale") importation alimentaire', langue: 'fr' },
  { q: 'interdiction exportation (maïs OR riz OR oignon OR céréales OR bétail)', langue: 'fr' },
  { q: 'Cameroun exportation (cacao OR café OR poivre OR banane OR manioc)', langue: 'fr' },
  { q: 'ZLECAf agriculture', langue: 'fr' },
  { q: 'Nigeria food import (maize OR rice OR onion OR cassava OR poultry)', langue: 'en' },
  { q: 'Africa importers suppliers (cocoa OR cashew OR sesame OR ginger)', langue: 'en' },
  { q: 'Cameroon export (cocoa OR coffee OR pepper OR banana OR cassava)', langue: 'en' },
];
const joursActualites = 3; // n'aller chercher que les articles des 3 derniers jours

// 7) Pays et régions suivis pour les appels d'offres de la Banque mondiale (noms exacts en anglais)
const paysAppelsOffres = [
  'Cameroon', 'Chad', 'Central African Republic', 'Congo, Republic of', 'Gabon', 'Nigeria',
  'Congo, Democratic Republic of', 'Niger', "Cote d'Ivoire", 'Senegal', 'Ghana', 'Benin', 'Togo', 'Mali',
  'Burkina Faso', 'Guinea', 'Western and Central Africa', 'Central Africa', 'Africa',
];

return [
  {
    json: { email, googleSheetUrl, mesProjets, motsCles, motsAlerte, motsCommerce, recherchesActualites, joursActualites, paysAppelsOffres },
  },
];

// Met les appels d'offres de la Banque mondiale au format commun des signaux.
// On ne garde que ceux dont la date limite n'est pas dépassée.
const MOIS = { Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06', Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12' };
const enIso = (d) => {
  const m = /^(\d{2})-(\w{3})-(\d{4})$/.exec(d || '');
  return m ? `${m[3]}-${MOIS[m[2]] || '01'}-${m[1]}` : '';
};
const aujourdhui = $now.toISODate();

const sorties = [];
for (const n of $input.first().json.procnotices || []) {
  const dateLimite = (n.submission_deadline_date || '').slice(0, 10);
  if (dateLimite && dateLimite < aujourdhui) continue;
  sorties.push({
    json: {
      id: `bm:${n.id}`,
      type: "Appel d'offres",
      source: 'Banque mondiale',
      date: enIso(n.noticedate),
      pays: n.project_ctry_name || '',
      titre: n.bid_description || n.project_name || '',
      lien: `https://projects.worldbank.org/en/projects-operations/procurement-detail/${n.id}`,
      acheteur: n.contact_organization || '',
      contact: [n.contact_name, n.contact_email, n.contact_phone_no].filter(Boolean).join(' · '),
      date_limite: dateLimite,
      texte: n.bid_description || '',
    },
  });
}
return sorties;

// Une adresse de flux RSS Google Actualités par recherche
const p = $input.first().json;
const LANGUES = { fr: 'hl=fr&gl=FR&ceid=FR:fr', en: 'hl=en-US&gl=US&ceid=US:en' };
return p.recherchesActualites.map((r) => ({
  json: {
    url: `https://news.google.com/rss/search?q=${encodeURIComponent(`${r.q} when:${p.joursActualites}d`)}&${LANGUES[r.langue] || LANGUES.fr}`,
  },
}));

// Met les articles au format commun des signaux
const sorties = [];
for (const item of $input.all()) {
  const a = item.json;
  if (!a.link || !a.title) continue;
  // Google Actualités ajoute « - Nom du journal » à la fin du titre : on le retire
  const coupe = a.title.lastIndexOf(' - ');
  const titre = (coupe > 0 ? a.title.slice(0, coupe) : a.title).replace(/\s*-\s*$/, '');
  const journal = coupe > 0 ? a.title.slice(coupe + 3) : '';
  sorties.push({
    json: {
      id: `actu:${a.guid || a.link}`,
      type: 'Actualité',
      source: journal ? `Google Actualités (${journal})` : 'Google Actualités',
      date: (a.isoDate || '').slice(0, 10),
      pays: '',
      titre,
      lien: a.link,
      acheteur: '',
      contact: '',
      date_limite: '',
      texte: titre,
    },
  });
}
return sorties;

// Garde les signaux qui parlent de tes produits (et, pour les actualités, de commerce), repère les pays cités,
// marque les urgents et ne laisse passer que ceux jamais vus lors des passages précédents.
const p = $('Paramètres').first().json;
const aujourdhui = $now.toISODate();

const echapper = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const debutDeMot = (mot) => new RegExp(`(^|[^\\p{L}])${echapper(mot)}`, 'iu');
const motEntier = (mot) => new RegExp(`(^|[^\\p{L}])${echapper(mot)}($|[^\\p{L}])`, 'iu');
const motEntierOuDebut = (mot) => (mot.length <= 3 ? motEntier(mot) : debutDeMot(mot));
const reglesProduits = p.motsCles.map((m) => [m, debutDeMot(m)]);
const reglesAlerte = p.motsAlerte.map((m) => [m, debutDeMot(m)]);
const reglesCommerce = p.motsCommerce.map((m) => debutDeMot(m));
const reglesProjets = p.mesProjets.map((x) => [x.nom, x.mots.map(debutDeMot)]);
const BAISSE = ['baisse', 'chute', 'effondr', 'recul', 'plonge', 'drop', 'collapse', 'plunge', 'decline', 'slump', 'lose', 'loss'].map(debutDeMot);
const HAUSSE = ['hausse', 'flambée', 'envolée', 'record', 'pénurie', 'manque', 'rupture', 'interdi', 'shortage', 'surge', 'spike', 'soar', 'ban'].map(motEntierOuDebut);
const IMPORT = ['import'].map(debutDeMot);

// Nom français de chaque mot-clé (pour des briefs lisibles)
const EN_FRANCAIS = {
  maize: 'maïs', rice: 'riz', cassava: 'manioc', tapioca: 'manioc', gari: 'manioc', cocoa: 'cacao', coffee: 'café',
  pepper: 'poivre', chili: 'piment', ginger: 'gingembre', sesame: 'sésame', soybean: 'soja', soya: 'soja',
  groundnut: 'arachide', peanut: 'arachide', onion: 'oignon', potato: 'pomme de terre', 'pommes de terre': 'pomme de terre',
  cowpea: 'niébé', sorghum: 'sorgho', millet: 'mil', 'palm oil': 'huile de palme', banana: 'banane',
  pineapple: 'ananas', avocado: 'avocat', mango: 'mangue', cashew: 'cajou', shea: 'karité', kola: 'noix de cola',
  poultry: 'volaille', chicken: 'poulet', egg: 'œufs', oeuf: 'œufs', œuf: 'œufs', fish: 'poisson', seed: 'semences',
  semence: 'semences', fertili: 'engrais', 'animal feed': 'aliment pour bétail', flour: 'farine', cereal: 'céréales',
  céréale: 'céréales', grain: 'céréales', foodstuff: 'denrées alimentaires', 'food supply': 'denrées alimentaires',
  denrée: 'denrées alimentaires', vivres: 'denrées alimentaires', sugar: 'sucre',
};
const enFrancais = (mots) => [...new Set(mots.map((m) => EN_FRANCAIS[m] || m))];

// Le brief : ce qu'il faut retenir, et ce que tu peux en faire
function brief(s, produits, pays, projets) {
  const produit = produits.slice(0, 2).join(', ');
  const ou = pays ? ` (${pays})` : '';
  const concerne = projets.length ? `Concerne ton projet ${projets.join(' et ')}. ` : '';
  if (s.type === "Appel d'offres") {
    return {
      a_retenir: `${s.acheteur || 'Un acheteur public'}${ou} lance un appel d'offres : « ${s.titre} ». Date limite : ${s.date_limite || 'non précisée'}.`,
      que_faire: projets.length
        ? `${concerne}Lis le dossier (lien) : il faut en général une entreprise enregistrée et parfois une garantie. Si tu peux livrer, contacte l'acheteur avant la date limite (${s.contact || 'contact dans le dossier'}).`
        : `Tu ne produis pas ça. En apporteur d'affaires : signale cet appel d'offres à une entreprise camerounaise capable de livrer (${produit}) et propose de monter le dossier avec elle, contre une commission fixée par écrit.`,
    };
  }
  const titre = s.titre;
  let que;
  if (BAISSE.some((r) => r.test(s.titre))) {
    que = `Prix ou ventes en baisse pour ${produit}${ou} : prudence avant d'investir dans ce produit brut ; la transformation ou un acheteur engagé à l'avance protège mieux.`;
  } else if (HAUSSE.some((r) => r.test(s.titre))) {
    que = `Signe de manque ou de hausse pour ${produit}${ou} : si tu en as ou connais des producteurs, c'est le moment de contacter les acheteurs${pays ? ' de ce pays' : ''}.`;
  } else if (IMPORT.some((r) => r.test(s.titre))) {
    que = `${pays || 'Ce marché'} importe ${produit} : piste de vente ou de courtage, à creuser en cherchant les importateurs.`;
  } else if (projets.length) {
    que = `Lis-le : ça parle de ta filière. Note les entreprises, banques ou organismes cités : ce sont des contacts possibles.`;
  } else {
    que = `Information de contexte sur ${produit} : à lire si tu travailles sur ce produit, sinon rien à faire.`;
  }
  return { a_retenir: titre, que_faire: concerne + que };
}

const PAYS = [
  ['Cameroun', ['cameroun', 'cameroon']], ['Nigeria', ['nigeria']], ['Gabon', ['gabon']],
  ['Congo', ['congo', 'rdc', 'drc']], ['Tchad', ['tchad', 'chad']], ['Centrafrique', ['centrafrique', 'centrafricaine', 'central african']],
  ['Guinée équatoriale', ['guinée équatoriale', 'equatorial guinea']], ["Côte d'Ivoire", ["côte d'ivoire", "cote d'ivoire", 'ivory coast']],
  ['Ghana', ['ghana']], ['Sénégal', ['sénégal', 'senegal']], ['Bénin', ['bénin', 'benin']], ['Togo', ['togo']],
  ['Niger', ['niger']], ['Mali', ['mali']], ['Burkina Faso', ['burkina']], ['Guinée', ['guinée', 'guinea']],
  ['Maroc', ['maroc', 'morocco']], ['Algérie', ['algérie', 'algeria']], ['Tunisie', ['tunisie', 'tunisia']],
  ['Égypte', ['égypte', 'egypt']], ['Kenya', ['kenya']], ['Éthiopie', ['éthiopie', 'ethiopia']],
  ['Afrique du Sud', ['afrique du sud', 'south africa']], ['Angola', ['angola']], ['Tanzanie', ['tanzanie', 'tanzania']],
  ['France', ['france']], ['Belgique', ['belgique', 'belgium']], ['Pays-Bas', ['pays-bas', 'netherlands']],
  ['Allemagne', ['allemagne', 'germany']], ['Chine', ['chine', 'china']], ['Inde', ['inde', 'india']],
  ['Turquie', ['turquie', 'turkey', 'türkiye']], ['Émirats', ['émirats', 'emirates', 'uae', 'dubai', 'dubaï']],
  ['États-Unis', ['états-unis', 'united states', 'usa']],
].map(([nom, variantes]) => [nom, variantes.map(motEntier)]);

const memoire = $getWorkflowStaticData('global');
memoire.dejaVus ??= [];
const vus = new Set(memoire.dejaVus);

const sorties = [];
for (const item of $input.all()) {
  const s = item.json;
  if (!s.id || vus.has(s.id)) continue;
  const texte = s.texte || s.titre || '';
  const produits = reglesProduits.filter(([, r]) => r.test(texte)).map(([m]) => m);
  if (!produits.length) continue;
  if (s.type === 'Actualité' && !reglesCommerce.some((r) => r.test(texte))) continue;
  vus.add(s.id);
  memoire.dejaVus.push(s.id);

  const alertes = reglesAlerte.filter(([, r]) => r.test(texte)).map(([m]) => m);
  const paysCites = PAYS.filter(([, regles]) => regles.some((r) => r.test(texte))).map(([nom]) => nom);
  const projets = reglesProjets.filter(([, regles]) => regles.some((r) => r.test(texte))).map(([nom]) => nom);
  const pays = s.pays || paysCites.join(', ');
  const listeProduits = enFrancais(produits);
  sorties.push({
    json: {
      date_detection: aujourdhui,
      priorite: s.type === "Appel d'offres" || alertes.length || projets.length ? 'haute' : 'normale',
      concerne_projet: projets.join(', '),
      type: s.type,
      source: s.source,
      pays,
      produits: listeProduits.join(', '),
      titre: s.titre,
      ...brief(s, listeProduits, pays, projets),
      lien: s.lien,
      acheteur: s.acheteur,
      contact: s.contact,
      date_limite: s.date_limite,
      date: s.date,
      statut: 'nouveau',
      notes: '',
      id: s.id,
    },
  });
}

// La mémoire garde les 5 000 derniers signaux vus
memoire.dejaVus = memoire.dejaVus.slice(-5000);

const ordre = (o) => (o.concerne_projet ? 0 : 4) + (o.type === "Appel d'offres" ? 0 : 1) + (o.priorite === 'haute' ? 0 : 2);
sorties.sort((a, b) => ordre(a.json) - ordre(b.json) || String(b.json.date).localeCompare(String(a.json.date)));
return sorties;

// Met en forme l'alerte du jour : une fiche par signal avec ce qu'il faut retenir et ce que tu peux en faire.
// (Les 30 premiers signaux ; tout est dans la Google Sheet.)
const p = $('Paramètres').first().json;
const signaux = $input.all().map((i) => i.json);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const fiche = (s) => `
  <div style="border:1px solid #e3e8e6;border-radius:10px;padding:12px 14px;margin:0 0 10px">
    <div style="margin:0 0 6px;font-size:13px;color:#5a6a67">
      ${s.priorite === 'haute' ? '<b style="color:#b03434">● urgent</b> · ' : ''}${esc(s.type)}${s.pays ? ' · ' + esc(s.pays) : ''}${s.date_limite ? ' · date limite ' + esc(s.date_limite) : ''}
      ${s.concerne_projet ? `<span style="display:inline-block;margin-left:4px;padding:1px 8px;border-radius:999px;font-weight:600;color:#1f7a4d;background:#def0e5">${esc(s.concerne_projet)}</span>` : ''}
    </div>
    <div style="font-size:14px;margin:0 0 6px"><b>À retenir :</b> ${esc(s.a_retenir)} <a href="${esc(s.lien)}">Lire</a></div>
    <div style="font-size:14px"><b>Que faire :</b> ${esc(s.que_faire)}</div>
  </div>`;

const groupes = [
  ['Touche tes projets', signaux.filter((s) => s.concerne_projet)],
  ["Appels d'offres", signaux.filter((s) => !s.concerne_projet && s.type === "Appel d'offres")],
  ['Actualités', signaux.filter((s) => !s.concerne_projet && s.type !== "Appel d'offres")],
];
let reste = 30;
const blocs = groupes
  .filter(([, liste]) => liste.length)
  .map(([titre, liste]) => {
    const montres = liste.slice(0, Math.max(0, reste));
    reste -= montres.length;
    return montres.length ? `<h3 style="margin:18px 0 8px">${titre} (${liste.length})</h3>${montres.map(fiche).join('')}` : '';
  })
  .join('');

const nbAo = signaux.filter((s) => s.type === "Appel d'offres").length;
const nbProjets = signaux.filter((s) => s.concerne_projet).length;
const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;color:#13201e;max-width:760px">
  <h2 style="margin:0 0 4px">Veille Afrique : ${signaux.length} nouveaux signaux</h2>
  <p style="margin:0 0 8px;color:#5a6a67">Tout est rangé dans <a href="${esc(p.googleSheetUrl)}">ta Google Sheet</a>, onglet « Signaux ». Mets à jour la colonne « statut » quand tu as contacté quelqu'un.</p>
  ${blocs}
</div>`;

const details = [nbProjets && `${nbProjets} sur tes projets`, nbAo && `${nbAo} appel(s) d'offres`].filter(Boolean).join(', ');
return [{ json: { sujet: `Veille Afrique : ${signaux.length} nouveaux signaux${details ? ` (${details})` : ''}`, html } }];
